namespace Dependinator.Core.Shared;

// The built-in demo models: pre-parsed, gzip-compressed item lists generated by
// ./scripts/gen-demo (src/Dependinator.DemoGen) into the Wasm wwwroot, where the browser app
// downloads them, and embedded into the parser libraries, so the Web/LSP hosts load them without
// parsing. "/Demo.sln" is this solution renamed "Demo"; "/Demo.bicep" is the webshop example
// deployment (examples/bicep).
static class DemoModel
{
    public static string DemoSolutionName = "/Demo.sln";
    public static string WorkingSolutionPath = "/workspaces/Dependinator/Dependinator.sln";
    public static string DemoModelName = "demo.model";
    public static string DemoOutputPath = $"/workspaces/Dependinator/src/Dependinator.Wasm/wwwroot/{DemoModelName}";

    public static string DemoBicepName = "/Demo.bicep";
    public static string WorkingBicepPath = "/workspaces/Dependinator/examples/bicep/webshop.bicep";
    public static string DemoBicepModelName = "demo-bicep.model";
    public static string DemoBicepOutputPath =
        $"/workspaces/Dependinator/src/Dependinator.Wasm/wwwroot/{DemoBicepModelName}";

    public static IReadOnlyList<string> DemoNames => [DemoSolutionName, DemoBicepName];

    public static bool IsDemo(string path) => path == DemoSolutionName || path == DemoBicepName;

    // The static asset (in the Wasm wwwroot) holding a demo model's items.
    public static string ModelFileName(string demoPath) =>
        demoPath == DemoBicepName ? DemoBicepModelName : DemoModelName;

    // In test mode always use the embedded demo model (no parsing); otherwise the Web
    // host parses the working solution and other hosts use the embedded demo model.
    public static string Path => Build.IsTestMode || !Build.IsWeb ? DemoSolutionName : WorkingSolutionPath;

    // The demo models offered in the Models menu: the browser app has nothing else to open
    // locally, and the test host uses them for determinism. The Web dev host and VS Code open
    // real files instead (the demos stay reachable through share links and the startup fallback).
    public static IReadOnlyList<string> ListedPaths => Build.IsTestMode || Build.IsStandaloneWasm ? DemoNames : [];
}
